import{_ as s,c as t,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"杨氏易传卷二十","description":"杨氏易传 - 杨氏易传卷二十","frontmatter":{"title":"杨氏易传卷二十","description":"杨氏易传 - 杨氏易传卷二十"},"headers":[],"relativePath":"zh/classics/yangshi/021.md","filePath":"zh/classics/yangshi/021.md"}'),r={name:"zh/classics/yangshi/021.md"};function i(c,a,o,p,d,h){return l(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"杨氏易传卷二十",tabindex:"-1"},[n("杨氏易传卷二十 "),e("a",{class:"header-anchor",href:"#杨氏易传卷二十","aria-label":"Permalink to “杨氏易传卷二十”"},"​")],-1),e("p",null,"钦定四库全书",-1),e("p",null,"宋杨简撰。",-1),e("p",null,"今人言易者必本于乾、坤，陋矣。但见周易之书，不见连山、归藏之书，故必首乾次坤。不知连山首艮、重艮，故曰连山；归藏首坤，故曰乾、坤之义。连山，夏后氏之易；归藏，商人之易。至矣哉！合三易而观之，而后八卦之妙，大易之用，混然一贯之道，昭昭于天下矣。三方皆易也，三才之变，非一实一，或杂焉，或纯焉。纯焉其名乾、坤，杂焉其名震、坎、艮、巽、离、兑，皆是物也。一物而八名也，初无大小优劣之间也。形则有大小，道无大小；德则有优劣，道无优劣。或首艮，或首坤，明乎八卦之皆易也。易道则变而为八，其变虽八，其道实一。曰连山宓戏，归藏黄帝。易卦诸彖言「大矣哉」者，十二卦而已。豫、遁、姤、旅言时义，随言随时之义，岂他卦皆无时义哉？岂他卦之时义皆不大哉？坎、暌、蹇言时用，岂他卦皆无时用哉？岂他卦之时用皆不大哉？颐、大过、解、革言时，岂他卦皆非时哉？岂他卦之时皆不大哉？六十四卦皆时也，皆有义也，皆有用也，皆大也。「大矣哉」，盖叹其道之大，有言不能尽之意。事无大小，无非易道之妙。圣人偶于此十二卦偶发其数，非此十二卦与他卦特异也，使每卦而言，则不胜其言。愚者执其言，智者通其意，岂特六十四卦皆可称「大矣哉」，虽三百八十四爻亦皆可称「大矣哉」！圣人于豫、随、遁、姤、旅，则犹有义之可言；于坎、暌、蹇，则犹有用之可言。至于颐、大过、解、革，则既不曰「义」，又不曰「用」，止曰「时」而已，夫何以曰「大矣哉」？於戏！此正明以天地无一物一事一时之非易。学者溺于思虑，必求其义。圣人于颐、大过、解辈，尽捐义用，止言其时，而叹之曰「大矣哉」。使学者无所求索，不容钩深，即时而悟「大哉」之妙，则事理一贯，精粗一体，孔子「何思何虑」，文王「不识不知」，信矣。需，有孚，光，亨，贞吉。言需得其道，必得所需。需，待也。彼此相孚则应矣。所需待多动乎意，非光也。光如日月之光，无思无为而无所不照，此之谓道。如此人咸信之，故曰「孚」。如此则得所需矣，亨矣。得所需亨通，或放逸失正，故又曰「贞乃吉」。孚与光与正，本非三事，以三言发明道心。一动乎意，则不孚不光不正，谓之人心。故舜曰：「人心惟危。」明其即入于邪，入于凶祸。坤",-1),e("p",null,"六二：「直方大，不习无不利。」直心而往，即易之道。意起则爻而入于邪矣。直心而行，虽遇万变而不转易，是之谓「方」。圆则转，方则不转。方者，特明不转之义，非于直之外又有方也。夫道一而已矣，言之不同，初无二致。是道甚大，故曰「大」。是道非学习之所能，故曰「不习」。孟子曰：「人之所不学而能者，其良能也；所不虑而知者，其良知也。」习者勉强，本有者奚俟乎习？此虽人道，即地之道，故曰「地道光」也。光如日月之光，无思无为而无所不照，不光明者也。必入于意，必支而他，必不直方，必昏，必不利。六三「含章可贞」，",-1),e("p",null,"阴虽有美，含之以从王事，弗敢成也。地道也，妻道也，臣道也。地道无成而「代有终」也。惑者往往于是疑其为小，故圣人特发之曰「智光大」也。道一而已，初无小大。",-1),e("p",null,"六四「括囊，无咎无誉」，亦此道也。方时闭塞，义当括囊而谨易道之见于坤，见于谨者也。二言坤道之正，五言坤道之盛，他卦之五多明君象，至于坤，明臣道也，故五止言臣位之极盛。黄者中之义，言乎其得中道也，故曰「通理」。言理以明中，非中自中，理自理也。裳者下服，言乎正人臣之位，居人臣之体也，故曰「正位居体」。明乎得道者必守常分而不犯，此非设饰者所能由中而发于文为，故曰「元吉，文在中也」，言乎文非外饰，乃自中诚而著也。伊周之事，人咸信之，不疑其为非，信其识也。王莽设饰，故卒罹大祸。初之「履霜」，谨微之道；上六之「龙战」，道之穷也。皆易之道，而有昏明邪正之辨也。",-1),e("p",null,"「坤」之用六，即乾之用九，九六不同而用同。「乾」造始，「坤」代终，始终不同而其大则同，故曰「以大终」也。「至哉」之坤，即「大哉」之乾也，名分不同而道同也。为妻为臣而失道，则不永，则不贞；得其道者，必永必贞。二三四五皆能用六，惟上六不能用六，反为六所用，为形体所使，为势位所动，故曰初亦不能用六，故为霜，为永，为不善之积，能辨之于早，则能用之矣。小畜柔得位而上下应之，曰小畜。健而巽，刚中而志行，乃亨。小畜，以臣畜君之道也。畜有养义，有止义。以下畜上，非势之顺者，而有道焉，非柔则不敬不顺，非得位则不可以有所行，岂有居下位而可以行畜之事者乎？柔虽得位，使人心不悦，虽悦而不至于上下皆悦而应之，亦不能以畜君。天下事未有人心不悦而能行者，而况于畜君乎？故必上下之心咸应之乃可。其德健则力足以行其事，而无困慑不继之患；巽则顺入乎君心，刚则物莫能变，中则不偏不倚。刚中两言，足以发明道心之本。人臣能健能巽，而中无其本，亦不能致亨。健矣，巽矣，刚矣，中矣。或所畜之君虽略相应，而谏不尽行，言不尽听，则臣亦不可谓得行其志，亦不能亨。於戏！物情事理，如上所序，节节如此，曲折如此，乃易之道也。惟柔得位，以明六四之象；众阳咸应，有上下应之象。下乾，健象；上巽，巽象；刚中，二五之象；四五刚柔相得，有志行之象。非象自象，道自道也。此正易道之见于小畜六画者然也。象著其义，彖发其义。柔也，得位也，上下应也，健也，巽也，刚也，中也，志行也，非每事而致其力也。合是数者，以发明易小畜之道。得易道全者，自能当小畜之时，尽小畜之义，自与此彖辞无不合也。有一不合，必于道有亏焉。齐景公悦晏子之对，作君臣相悦之乐，其诗曰：「畜君何尤？」畜君者，好君也，此亦小畜之「小亨」也。何者？晏子犹未有刚中之大本故也。易者，天下之大道。圣人之大道，虽甚贤者，未能尽也。虽高明之士，已得大本，而物情事理，委曲万变，往往疏略，不能皆尽。孔子自谓「加我数年，五十以学易，可以无大过。」明知夫易者，大圣人之事，应变无穷之道，晚年成德，乃可学也。少读易大传，深爱「无思也，无为也，寂然不动，感而遂通天下之故」。窃自念学道必造此妙。及他日读论语孔子哭颜渊至于恸，从者曰：「子恸矣。」曰：「有恸乎？」则孔子自不知其为恸，殆非所谓无思无为、寂然不动者。至于不自知，则又几于不清明，怀疑于中，往往一二十年。及承教于象山陆先生，闻举扇讼之是非，忽觉某心乃如此清明，虚灵妙用之应，无不可者。及后居姚氏丧，哀恸切痛，不可云喻。既久，略省察曩正哀恸时，乃亦寂然不动，自然不自知，方悟孔子哭颜渊至于恸矣而不自知，正合无思无为之妙，益信吾心有此神用妙用。其哀苦至于如此其极，乃其变化。故易大传又曰：「变化云为」，不独其有此心，举天下万古之人皆有此心，益信人皆与尧舜禹汤文武周公孔子同此心，顾人不自知、不自信尔。子曰：「书不尽言，言不尽意。」然则圣人之意，其不可见乎？子曰：「圣人立象以尽意，设卦以尽情伪，繋辞焉以尽其言，变而通以尽利，鼓之舞之以尽神。」至哉圣言，岂训诂之所能解？既曰「书不尽言」矣，又曰「繋辞以尽言」；既曰「言不尽意」矣，又曰「立象以尽意」。于乎至哉！似矛盾而非矛盾也，似异而实同也。圣人之言意，岂尽不尽之所可言？言尽亦可，言不尽亦可。云不尽者，圣人之实言；云「尽」者，亦圣人之实言。此唯智者足以知其解者，始信「天下何思何虑」，始信「孔子无隐于二三子」，始信六十四卦卦卦齐一，始信「三百八十四爻爻爻不昧」。六十四卦皆可以言「元亨利贞」。圣人既于乾言之，又于坤言之，又于屯言之。圣人于此，谓学者可以意通之矣。故自蒙而下，或言其一，或言其二，或言其三，至随又全言之，临又言之，无妄、革又言之，亦偶于此数卦而复言，非此卦之特异也。亦恐学者执乾、坤、屯之卦异余卦，故复于此言之，以破其疑。于坤曰「牝马之贞」者，于以明地道也，妻道也，臣道也，柔顺勤行之道也。刚上在阳，无为而佚，君之道也。柔阴在下，有为而劳，臣之道也。君臣之分不同，而道则同也。在君则刚、则佚，在臣则柔、则劳，一也。天下之动，贞夫一者也，无二贞也。子思曰：天地之道，其为物不二。使牝马之贞果劣于乾，则屯不言牝马，又其失实者犹多，而况于下焉者乎？易大传曰：「古者包牺氏之王天下，仰则观象于天，俯则观法于地，观鸟兽之文与地之宜，近取诸身，远取诸物，于是始作八卦。」某尝谓大传非圣人作，于是乎益验。此一章乃不知道者推测圣人意其如此甚矣。夫道之不明也久矣，未有一人知大传之非者。惟「子曰」下乃圣人之言，余则非。何以明此章之非？舜曰「道心」，明此心之即道，动乎意则失天性而为人心。孔子曰：「心之精神是谓圣」，禹曰「安汝止」，正明人心本寂然不动，动静云为，乃此心之神用，如明鉴照物，大小远近，参错毕见，而非为也，非动也。天象、地法、鸟兽之文、地之宜，与凡在身及在物，皆在乎此心光明之中，非如此一章辞气之劳也。此可与知道者语，未知道者必不信。杨氏易传卷二十",-1)])])}const _=s(r,[["render",i]]);export{m as __pageData,_ as default};
